"""fa18: hand-written gfx950 assembly FMHA (generated by pika_h3/fa18/fa18gen.py).

Exact attention: bf16 Q/K/V, fp32 scores / softmax / accumulation, exact lazy rescale (the running max is always exact,
O and l rescaled when it rises), row sum of the bf16 P on the matrix core, one final bf16 rounding.  Speed = aiter mha_v4
(+-1 % at world 8), precision above v3 (v4 sits up to 0.25 dB below v3 at 5 s).  Inputs are the strided [1, n, h, 128]
views of the all-to-all buffer (no copies, no V transpose); optional natural-log LSE [h, Nq] for the LSE-merge paths.

Enabled by PIKA_V4_IMPL=fa18 (default 'aiter'): it replaces the kernel inside sp_model._v4_into / _attn_lse only, so every
PIKA_ATTN_KERNEL=v4 code path (split, tail, SDMA) is unchanged.  The kernel is generated + assembled at first use (before
EAT_READY) into a cache directory shared by the ranks (file lock + atomic rename)."""
import ctypes, fcntl, hashlib, os, subprocess, sys, tempfile
import torch

_SRC = os.path.join(os.path.dirname(os.path.abspath(__file__)), "fa18")
GEN_ARGS = ["LA=4", "SPLITLD=1", "VTR=1"]
_lib = None


def _build():
    files = ["fa18gen.py", "fa18_pro.inc", "fa18_epi.inc", "fa17_host.cpp"]
    h = hashlib.sha1()
    for f in files:
        h.update(open(os.path.join(_SRC, f), "rb").read())
    h.update(" ".join(GEN_ARGS).encode())
    from .paths import cache_dir
    root = cache_dir("fa18", env="PIKA_FA18_DIR")
    out = os.path.join(root, h.hexdigest()[:16])
    so = os.path.join(out, "libfa18.so")
    if os.path.exists(so) and os.path.exists(os.path.join(out, "libfa18.co")):
        return so
    os.makedirs(root, exist_ok=True)
    with open(os.path.join(root, ".lock"), "w") as lk:
        fcntl.flock(lk, fcntl.LOCK_EX)
        if os.path.exists(so):
            return so
        tmp = tempfile.mkdtemp(dir=root)
        rocm = os.environ.get("ROCM_PATH", "/opt/rocm")
        s = os.path.join(tmp, "fa18.s")
        subprocess.check_call([sys.executable, os.path.join(_SRC, "fa18gen.py"), s] + GEN_ARGS, stdout=subprocess.DEVNULL)
        subprocess.check_call([f"{rocm}/llvm/bin/clang", "-x", "assembler", "-target", "amdgcn-amd-amdhsa", "-mcpu=gfx950",
                               "-c", s, "-o", os.path.join(tmp, "fa18.o")])
        subprocess.check_call([f"{rocm}/llvm/bin/ld.lld", "-shared", os.path.join(tmp, "fa18.o"),
                               "-o", os.path.join(tmp, "libfa18.co")])
        subprocess.check_call([f"{rocm}/bin/hipcc", "-O2", "-shared", "-fPIC", os.path.join(_SRC, "fa17_host.cpp"),
                               "-o", os.path.join(tmp, "libfa18.so"), "-ldl"])
        os.replace(tmp, out) if not os.path.exists(out) else None
    return so


def _get():
    global _lib
    if _lib is None:
        lib = ctypes.CDLL(_build())
        lib.fa18_launch.restype = ctypes.c_int
        _lib = lib
    return _lib


def fa18_into(q, k, v, out, lse=None):
    """q [1, Nq, h, 128], k/v [1, N, h, 128] bf16 views (last dim contiguous); out [1, Nq, h, 128]; lse fp32 [h, Nq] or None."""
    assert q.dtype == torch.bfloat16 and q.shape[-1] == 128 and q.shape[0] == 1
    for t in (q, k, v, out):
        assert t.stride(-1) == 1
    _, Nq, h, D = q.shape
    N = k.shape[1]
    if lse is not None:
        assert lse.dtype == torch.float32 and lse.is_contiguous() and lse.numel() == h * Nq
    st = torch.cuda.current_stream(q.device).cuda_stream
    r = _get().fa18_launch(
        ctypes.c_void_p(q.data_ptr()), ctypes.c_void_p(k.data_ptr()), ctypes.c_void_p(v.data_ptr()),
        ctypes.c_void_p(out.data_ptr()), ctypes.c_void_p(lse.data_ptr() if lse is not None else 0),
        ctypes.c_longlong(q.stride(1)), ctypes.c_longlong(q.stride(2)), ctypes.c_longlong(k.stride(1)), ctypes.c_longlong(k.stride(2)),
        ctypes.c_longlong(v.stride(2)), ctypes.c_longlong(v.stride(1)), ctypes.c_longlong(out.stride(1)), ctypes.c_longlong(out.stride(2)),
        ctypes.c_int(Nq), ctypes.c_int(N), ctypes.c_int(h), ctypes.c_float(D ** -0.5), ctypes.c_void_p(st))
    if r != 0:
        raise RuntimeError(f"fa18_launch failed: {r}")
    return out


def fa18_lse(q, k, v):
    """BHSD views [1, h, n, 128] -> (o [1, h, Nq, 128] view, lse fp32 [1, h, Nq]) like sp_model._flash_lse."""
    q4, k4, v4 = (x.transpose(1, 2) for x in (q, k, v))
    _, Nq, h, D = q4.shape
    o = torch.empty((1, Nq, h, D), dtype=q.dtype, device=q.device)
    lse = torch.empty((1, h, Nq), dtype=torch.float32, device=q.device)
    fa18_into(q4, k4, v4, o, lse[0])
    return o.transpose(1, 2), lse
